    adcs_vec3_t u;
    double norm_axis;
    double cos_a, sin_a;
    double dot_uv;
    adcs_vec3_t term1, term2, term3;
    adcs_vec3_t cross_uv;

    /* Null pointer checks */
    if ((vector == NULL) || (axis == NULL) || (rotated == NULL)) {
        if (rotated != NULL) {
            rotated->x = 0.0;
            rotated->y = 0.0;
            rotated->z = 0.0;
        }
        return ADCS_E_NULL;
    }

    /* Finite value checks */
    if (!adcs_is_finite_vec3(vector) || !adcs_is_finite_vec3(axis) || !isfinite(angle_rad)) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    /* Axis must be non-zero */
    norm_axis = adcs_vec3_norm(axis);
    if (norm_axis <= FLT64_ZERO || !isfinite(norm_axis)) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    /* Normalize axis to get unit vector u */
    u.x = axis->x / norm_axis;
    u.y = axis->y / norm_axis;
    u.z = axis->z / norm_axis;

    /* Precompute trigonometric values */
    cos_a = cos(angle_rad);
    sin_a = sin(angle_rad);

    /* Compute dot product u . v */
    dot_uv = adcs_vec3_dot(&u, vector);

    /* Term 1: v * cos(a) */
    term1 = adcs_vec3_scale(vector, cos_a);

    /* Term 2: (u cross v) * sin(a) */
    cross_uv = adcs_vec3_cross(&u, vector);
    term2 = adcs_vec3_scale(&cross_uv, sin_a);

    /* Term 3: u * (u . v) * (1 - cos(a)) */
    term3 = adcs_vec3_scale(&u, dot_uv * (1.0 - cos_a));

    /* Result = Term 1 + Term 2 + Term 3 */
    *rotated = adcs_vec3_add(&term1, &term2);
    *rotated = adcs_vec3_add(rotated, &term3);

    return ADCS_OK;
}

